def main():
    force = "--force" in sys.argv
    w = s = 0
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(A)), mode="r:gz") as t:
        for m in t.getmembers():
            if not m.isfile(): continue
            if os.path.exists(m.name) and not force:
                s += 1; continue
            d = os.path.dirname(m.name)
            if d: os.makedirs(d, exist_ok=True)
            open(m.name,"wb").write(t.extractfile(m).read())
            w += 1; print("  wrote", m.name)
    for d in ("scripts","output","work","music","posts","brand"):
        os.makedirs(d, exist_ok=True)
    if not os.path.exists("posted_log.csv"):
        open("posted_log.csv","w").write("posted_at,slug,status,media_id,note\n")
    if not os.path.exists("calendar_60.csv"):
        print("  planning 60 days"); subprocess.run([sys.executable,"calendar_60.py"],check=False)
    print(f"bootstrap: {w} written, {s} present")

if __name__ == "__main__":
    main()
